   "due": "num(it.get('past_due'))",
   "floor": "(int(f['due'] * 50 + 0.5 + 1e-9) / 100.0) if it.get('type') == 'car_loan' else first_num(it.get(by_value(it.get('type'), {'credit_card': 'minimum_payment', 'personal_loan': 'instalment_amount'}, '')), f['due'])",
   "floor_spoken": "by_value(it.get('type'), {'credit_card': 'minimum payment', 'personal_loan': 'instalment amount', 'car_loan': 'half of the overdue amount'}, 'minimum')",
   "deadline": "rule_date(T['limit'], today)"
  },
  "limit_field": "deadline",
  "text": "{n}. product_id {id} = \"{label}\". Overdue amount {due_m}, {days_late} days overdue, tier {tier}. Minimum ({floor_spoken}): {floor_m}. Acceptable amount: {floor_m} to {due_m}. Deadline (latest date): {deadline_say} ({deadline_iso}).",
  "ladder": {
