 "tools": {
  "verify_identity": {
   "role": "verify",
   "description": "Check one security answer. CALL it every time the customer answers a security question, with that one answer.",
   "fields": {
    "field": {"description": "Which question this answer is for."},
    "answer": {"description": "phone_last4 as four digits; date_of_birth as YYYY-MM-DD (a date given only in numbers is day, month, year)."}
   }
  },
  "get_account": {"role": "fetch"},
  "create_promise": {
   "role": "record",
